 2→
 3→import java.io.IOException;
 4→import java.util.*;
 5→
 6→import com.fasterxml.jackson.core.*;
 7→import com.fasterxml.jackson.databind.DeserializationContext;
 8→import com.fasterxml.jackson.databind.JsonDeserializer;
 9→import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
10→import com.fasterxml.jackson.databind.util.NameTransformer;
11→import com.fasterxml.jackson.databind.util.TokenBuffer;
12→
13→/**
14→ * Object that is responsible for handling acrobatics related to
15→ * deserializing "unwrapped" values; sets of properties that are
16→ * embedded (inlined) as properties of parent JSON object.
17→ */
18→public class UnwrappedPropertyHandler
19→{
20→    protected final List<SettableBeanProperty> _properties;
21→
22→    public UnwrappedPropertyHandler()  {
23→        _properties = new ArrayList<SettableBeanProperty>();
24→    }
25→
26→    protected UnwrappedPropertyHandler(List<SettableBeanProperty> props)  {
27→        _properties = props;
28→    }
29→
30→    public void addProperty(SettableBeanProperty property) {
31→        _properties.add(property);
32→    }
33→
34→    public UnwrappedPropertyHandler renameAll(NameTransformer transformer)
35→    {
36→        ArrayList<SettableBeanProperty> newProps = new ArrayList<SettableBeanProperty>(_properties.size());
37→        for (SettableBeanProperty prop : _properties) {
38→            String newName = transformer.transform(prop.getName());
39→            prop = prop.withSimpleName(newName);
40→            JsonDeserializer<?> deser = prop.getValueDeserializer();
41→            if (deser != null) {
42→                @SuppressWarnings("unchecked")
43→                JsonDeserializer<Object> newDeser = (JsonDeserializer<Object>)
44→                    deser.unwrappingDeserializer(transformer);
45→                if (newDeser != deser) {
46→                    prop = prop.withValueDeserializer(newDeser);
47→                }
48→            }
49→            newProps.add(prop);
50→        }
51→        return new UnwrappedPropertyHandler(newProps);
52→    }
53→
54→    @SuppressWarnings("resource")
55→    public Object processUnwrapped(JsonParser originalParser, DeserializationContext ctxt,
56→            Object bean, TokenBuffer buffered)
57→        throws IOException
58→    {
59→        for (int i = 0, len = _properties.size(); i < len; ++i) {
60→            SettableBeanProperty prop = _properties.get(i);
61→            JsonParser p = buffered.asParser(originalParser.streamReadConstraints());
62→            p.nextToken();
63→            prop.deserializeAndSet(p, ctxt, bean);
64→        }
65→        return bean;
66→    }
67→}

